				</div>
					</div>
				</div>
		<div class="elementor-element elementor-element-2197ad6 e-flex e-con-boxed e-con e-child" data-id="2197ad6" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
